@extends('layouts.storefront')
@section('title','My Account | MEETA')
@push('styles')<style>.account-page{padding-top:55px}.account-grid{display:grid;grid-template-columns:250px 1fr;gap:42px;margin-top:30px}.account-card,.account-main{border:1px solid var(--line);background:#fff;padding:26px}.profile-avatar{width:76px;height:76px;border-radius:50%;display:grid;place-items:center;background:#f1e3da;color:var(--brown);font-size:28px;overflow:hidden}.profile-avatar img{width:100%;height:100%;object-fit:cover}.account-links a{display:block;padding:13px 0;border-bottom:1px solid #eee;color:var(--muted)}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:25px 0}.stat-card{background:#fff8f3;border:1px solid var(--line);padding:20px}.stat-card strong{display:block;font-size:28px;color:var(--brown)}@media(max-width:750px){.account-grid{grid-template-columns:1fr}.stat-grid{grid-template-columns:1fr 1fr}}</style>@endpush
@section('content')<main class="account-page wrap"><h1>My Account</h1><p>Manage your collection, orders and account preferences.</p><div id="accountContent"><div class="loading">Loading your account…</div></div></main>@endsection
@push('scripts')<script>if(!protectPage())throw new Error('Authentication required');api('/api/customer/account/dashboard').then(({data})=>{const u=data.profile,name=u.display_name||u.full_name||u.first_name,avatar=u.profile_image_url?`<img src="${u.profile_image_url}" alt="${name}">`:name.charAt(0).toUpperCase();document.getElementById('accountContent').innerHTML=`<div class="account-grid"><aside class="account-card"><div class="profile-avatar">${avatar}</div><h2>${name}</h2><p>${u.email}</p><nav class="account-links"><a href="/account">Profile overview</a><a href="/orders">Order history</a><a href="/wishlist">My wishlist</a><a href="/checkout">Addresses & checkout</a></nav></aside><section class="account-main"><h2>Namaste, ${u.first_name}</h2><p>Welcome back to your collection of stories and craftsmanship.</p><div class="stat-grid">${Object.entries(data.counts).slice(0,4).map(([key,value])=>`<div class="stat-card"><strong>${value}</strong><span>${key.replaceAll('_',' ')}</span></div>`).join('')}</div><h2>Recent orders</h2>${data.recent_orders.length?data.recent_orders.map(order=>`<p><a href="/orders"><strong>${order.order_number}</strong></a> · ${order.order_status} · ₹${Number(order.total_amount).toLocaleString('en-IN')}</p>`).join(''):'<p>No orders yet. <a href="/categories" style="color:var(--brown)">Explore crafts</a></p>'}</section></div>`}).catch(error=>toast(error.message));</script>@endpush
